"""Invoke the unchanged Delphi diff classifier with positive public discovery.
Private paths are outside discovery, not post-filtered. No product mutation.
"""
from pathlib import Path
import importlib.util, subprocess, sys, json, hashlib
root=Path('/mnt/c/unifast/leadshug/leadshug_now_docker')
spec=importlib.util.spec_from_file_location('stcon05_diff_guard',root/'delphi-ai/tools/todo_diff_expectation_guard.py')
m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
public={
 root: ['.github','scripts','README.md','docker-compose.yml','docker-compose.channels.yml','docker-compose.testing.yml','Dockerfile','.dockerignore','.gitignore','.gitmodules','AGENTS.md','package.json','package-lock.json'],
 root/'api-app':['src','test','prisma','package.json','package-lock.json','.env.example','.dockerignore','.gitignore','docker/entrypoint.sh','Dockerfile','eslint.config.mjs','nest-cli.json','railway.json','tsconfig.json','tsconfig.build.json','vitest.config.ts','vitest.config.e2e.ts','vitest.config.cov.ts'],
 root/'web-app':['src','e2e','public','package.json','package-lock.json','index.html','playwright.config.ts','tsconfig.json','vite.config.ts','railway.json','.gitignore','.dockerignore','Dockerfile','docker/40-config-js.sh','nginx/default.conf.template'],
 root/'foundation_documentation':None,
}
commands=[]
def public_git(repo,args,*,check=True):
 repo=repo.resolve()
 repo=next((known for known in public if str(known).casefold()==str(repo).casefold()),repo)
 if repo not in public:raise RuntimeError('Repository outside the approved topology')
 args=list(args)
 if args[0] in ('diff','ls-files'):
  paths=public[repo]
  if args[0]=='diff':args.insert(1,'--ignore-submodules=all')
  if paths:
   if '--' not in args:args.append('--')
   args.extend(paths)
 elif args[0]!='rev-parse':raise RuntimeError('Unexpected guard Git operation')
 commands.append({'repository':str(repo.relative_to(root)),'arguments':args})
 winpath=subprocess.check_output(['wslpath','-w',str(repo)],text=True).strip()
 result=subprocess.run(['git.exe','-C',winpath,*args],check=check,capture_output=True,text=True,encoding='utf-8')
 if args==['rev-parse','--show-toplevel'] and result.returncode==0:
  translated=subprocess.check_output(['wslpath','-u',result.stdout.strip()],text=True).strip()
  translated=str(next((known for known in public if str(known).casefold()==translated.casefold()),Path(translated)))
  return subprocess.CompletedProcess(result.args,result.returncode,translated+'\n',result.stderr)
 return result
m.run_git=public_git
result=m.validate_todo(root/'foundation_documentation/todos/active/features/TODO-leadshug-official-template-authoring.md',root)
result['public_discovery_contract']={'mode':'positive pathspecs before all diff/untracked discovery','coverage':'API src/test/prisma and exact public manifests/configs; Web src/e2e/public and public configs; root public tooling/config; Foundation full','excluded_private_tree_inspected':False,'unchanged_classifier_sha256':hashlib.sha256((root/'delphi-ai/tools/todo_diff_expectation_guard.py').read_bytes()).hexdigest(),'wrapper_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'commands':commands}
if len(sys.argv)>1:Path(sys.argv[1]).write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(m.format_response(result))
raise SystemExit(2 if result['blocked'] else 0)
